   924          appendLength += sizeof(PrefixTlv) + BitVectorBytes(aPrefix.GetPrefixLength());
   925      }
   926
   927      if (dstHasRoute == NULL)
   928      {
   929          appendLength += sizeof(HasRouteTlv);
   930      }
   931
   932      appendLength += sizeof(HasRouteEntry);
   933
   934      VerifyOrExit(mLength + appendLength <= sizeof(mTlvs), error = OT_ERROR_NO_BUFS);
   935
   936      if (dstPrefix == NULL)
