   940          dstPrefix->Init(aPrefix.GetDomainId(), aPrefix.GetPrefixLength(), aPrefix.GetPrefix());
   941      }
   942
   943      if (aHasRoute.IsStable())
   944      {
   945          dstPrefix->SetStable();
   946      }
   947
   948      if (dstHasRoute == NULL)
   949      {
   950          dstHasRoute = static_cast<HasRouteTlv *>(dstPrefix->GetNext());
   951          Insert(reinterpret_cast<uint8_t *>(dstHasRoute), sizeof(HasRouteTlv));
   952          dstPrefix->SetLength(dstPrefix->GetLength() + sizeof(HasRouteTlv));
   953          dstHasRoute->Init();
   954
   955          if (aHasRoute.IsStable())
   956          {
   957              dstHasRoute->SetStable();
   958          }
   959      }
   960
   961      Insert(reinterpret_cast<uint8_t *>(dstHasRoute->GetNext()), sizeof(HasRouteEntry));
   962      dstHasRoute->SetLength(dstHasRoute->GetLength() + sizeof(HasRouteEntry));
   963      dstPrefix->SetLength(dstPrefix->GetLength() + sizeof(HasRouteEntry));
   964      memcpy(dstHasRoute->GetEntry(dstHasRoute->GetNumEntries() - 1), aHasRoute.GetEntry(0), sizeof(HasRouteEntry));
